class Solution { public boolean isValid(String code){Deque<String> stack=new ArrayDeque<>();boolean root=false;int index=0;while(index<code.length()){if(index>0&&stack.isEmpty())return false;if(code.startsWith("<![CDATA[",index)){if(stack.isEmpty())return false;int end=code.indexOf("]]>",index+9);if(end<0)return false;index=end+3;}else if(code.startsWith("</",index)){int end=code.indexOf('>',index+2);if(end<0)return false;String name=code.substring(index+2,end);if(!validName(name)||stack.isEmpty()||!stack.removeLast().equals(name))return false;index=end+1;}else if(code.charAt(index)=='<'){int end=code.indexOf('>',index+1);if(end<0)return false;String name=code.substring(index+1,end);if(!validName(name))return false;stack.addLast(name);root=true;index=end+1;}else{if(stack.isEmpty())return false;index++;}}return root&&stack.isEmpty();}private boolean validName(String name){if(name.length()<1||name.length()>9)return false;for(char c:name.toCharArray())if(c<'A'||c>'Z')return false;return true;} }
